package tv.vela.launcher;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import java.io.*;import java.lang.reflect.*;import java.net.URI;import java.util.*;

/** Owned synthetic loopback video; measures requests/lifecycle, not a physical TV's refresh switch. */
